import csv
import io


def totals(text):
    """Sum integer amounts per category from CSV text.

    The CSV must have a header row with columns ``category`` and ``amount``.
    Amounts are parsed as integers. Returns a dict mapping category name to
    the summed amount.

    Empty text or header-only input returns ``{}``. An invalid amount raises
    ``ValueError``.
    """
    if not text:
        return {}

    reader = csv.reader(io.StringIO(text))
    try:
        header = next(reader)
    except StopIteration:
        return {}

    # Normalize header names (strip whitespace) and locate column indices.
    header = [h.strip() for h in header]
    try:
        cat_idx = header.index("category")
        amt_idx = header.index("amount")
    except ValueError:
        raise ValueError("CSV must have 'category' and 'amount' columns")

    result = {}
    for row in reader:
        if not row:
            continue
        if len(row) <= cat_idx or len(row) <= amt_idx:
            raise ValueError("Row has missing columns")
        category = row[cat_idx].strip()
        amount_str = row[amt_idx].strip()
        try:
            amount = int(amount_str)
        except ValueError:
            raise ValueError("Invalid amount: %r" % amount_str)
        result[category] = result.get(category, 0) + amount

    return result
"}

