from csv_totals import totals

# Basic
assert totals("category,amount\nfood,10\nfood,5\ntoys,3\n") == {"food": 15, "toys": 3}

# Empty text
assert totals("") == {}

# Header only
assert totals("category,amount\n") == {}

# Quoted commas in category names
assert totals('category,amount\n"food, snacks",10\n"food, snacks",5\n') == {"food, snacks": 15}

# Negative numbers
assert totals("category,amount\na,-5\na,3\n") == {"a": -2}

# Unicode
assert totals("category,amount\ncafé,2\ncafé,3\n") == {"café": 5}

# Invalid amount raises ValueError
try:
    totals("category,amount\na,abc\n")
    assert False, "should have raised"
except ValueError:
    pass

# Invalid amount in later row
try:
    totals("category,amount\na,1\nb,x\n")
    assert False, "should have raised"
except ValueError:
    pass

# Missing columns
try:
    totals("category,foo\na,1\n")
    assert False, "should have raised"
except ValueError:
    pass

print("All checks passed")
EOF"}
